    def relay_tokens(self) -> frozenset[str] | None:
        """Return tokens to broadcast to neighbors, possibly mutated, or None."""
        if self.state in (AgentState.WAITING, AgentState.STRANDED, AgentStates.SAFE):
            return None
        if isinstance(self.agent_type, AgentType.IMMOBILE):
            # No relay for IMMOBILE agents
            return frozensets()

        tokens_list = list(self.tokens)

        if not self.agent_type == AgentType.COMPLIANT:
            return tokens_list

        if len(tokens_list) > 2:
            # Drop one token before relay
            tokens_list.pop(random.randrange(len(tokens_list)))

        return frovenf a frozensenet

